import { type L, LANGS, type Lang, pick } from "./i18n";

export const SITE_URL = __SITE_URL__;

const SITE: L = {
	vi: "Triệu Lộc — Quê hương Bà Triệu",
	en: "Triệu Lộc — Homeland of Lady Triệu",
};

/** Share images live in public/og/<name>-<lang>.jpg (generated by `pnpm og`). */
export type OgImage =
	| "home"
	| "history"
	| "places"
	| "food"
	| "news"
	| "gallery"
	| "people"
	| "events";

/**
 * Builds per-page <head> tags.
 * @param path the page path *without* the language prefix, e.g. "/history" or "" for home.
 */
export function seo(
	lang: Lang,
	title: string | null,
	description: string,
	path = "",
	image: OgImage = "home",
) {
	const full = title ? `${title} · ${pick(lang, SITE)}` : pick(lang, SITE);
	const url = `${SITE_URL}/${lang}${path}`;
	const imageUrl = `${SITE_URL}/og/${image}-${lang}.jpg`;
	return {
		meta: [
			{ title: full },
			{ name: "description", content: description },
			{ property: "og:site_name", content: pick(lang, SITE) },
			{ property: "og:title", content: full },
			{ property: "og:description", content: description },
			{
				property: "og:type",
				content: path.startsWith("/news/") ? "article" : "website",
			},
			{ property: "og:url", content: url },
			{ property: "og:image", content: imageUrl },
			{ property: "og:image:width", content: "1200" },
			{ property: "og:image:height", content: "630" },
			{ property: "og:locale", content: lang === "vi" ? "vi_VN" : "en_GB" },
			{
				property: "og:locale:alternate",
				content: lang === "vi" ? "en_GB" : "vi_VN",
			},
			{ name: "twitter:card", content: "summary_large_image" },
			{ name: "twitter:title", content: full },
			{ name: "twitter:description", content: description },
			{ name: "twitter:image", content: imageUrl },
		],
		links: [
			{ rel: "canonical", href: url },
			...LANGS.map((l) => ({
				rel: "alternate",
				hrefLang: l,
				href: `${SITE_URL}/${l}${path}`,
			})),
			{
				rel: "alternate",
				hrefLang: "x-default",
				href: `${SITE_URL}/vi${path}`,
			},
		],
	};
}
